# Let me solve this with a simple backtracking approach
# We need to assign each number 1-14 to one of 5 groups (0-4)
# Each group must sum to 21

def solve():
    n = 14
    num_groups = 5
    target = 21

    assignment = [-1] * (n + 1)  # assignment[i] = group for number i
    group_sums = [0] * num_groups

    def backtrack(num):
        if num > n:
            return all(s == target for s in group_sums)

        for g in range(num_groups):
            if group_sums[g] + num <= target:
                # Pruning: avoid symmetric solutions by ordering
                assignment[num] = g
                group_sums[g] += num
                if backtrack(num + 1):
                    return True
                group_sums[g] -= num
                assignment[num] = -1

                # If this group is empty, don't try other empty groups (symmetry breaking)
                if group_sums[g] == 0:
                    break

        return False

    if backtrack(1):
        return assignment[1:]
    return None

result = solve()
print("Assignment (1-indexed):", result)
if result:
    # Verify
    groups = [[] for _ in range(5)]
    for i, g in enumerate(result):
        groups[g].append(i + 1)
    for g_idx, grp in enumerate(groups):
        print(f"Group {g_idx}: {grp} = {sum(grp)}")
